    answer: ['C'],
    analysis: '真理的本性在于王观认识与客观实际相符合,检验一种认识足否定具理,既不能在主观认识领域内寻找,也不能从纯客观的范围来解决实践的特点是直接现实性,即它能把主观认识同客观实际联系起来加以比较对照,从而确定主观认识同客观实际是否符合。考点 5：社会存在发展的基础和基本结构了解社会存在、社会意识、生产方式、生产力及生产关系。理解唯心史观的根本缺陷，社会存在与社会的辩证关系。一、历史观的基本问题历史观是人们在认识社会历史现象、解决社会问题时所采取的根本观点。社会存在和社会意识的关系问题是历史观的基本问题。社会存在属于社会生活的物质方面，是社会实践和物质生活各种条件的总和，包括物质生活资料的生产、地理环境和人口因素；社会意识属于社会生活的精神方面，它既包括社会意识的各种形式，也包括社会心理与自发形成的风俗、习惯。如何处理社会存在和社会意识的关系是区分历史唯物主义和历史唯心主义的关键。在马克思主义哲学产生之前，所有的哲学派别，无论是唯心主义还是唯物主义都没有正确解决这个问题，因为它们都不理解物质生产实践在社会生活中的地位和作用，因而也不能理解社会的本质，不理解社会存在和社会意识的真实关系。马克思主义哲学深刻揭示了社会生活的实践本质，从而唯物地、辩证地解决了社会存在和社会意识的关系问题。马克思指出：“物质生活的生产方式制约着整个社会生活、政治生活和精神生活的过程。不是人们的意识决定人们的存在，相反，是人们的社会存在决定人们的意识。”社会存在决定社会意识，社会意识是社会存在的反映并能动地反作用于社会存在。二、唯物史观创立的意义唯物史观的创立是社会历史观的革命性变革，具有重大的理论和实践意义。(1)唯物史观的创立，实现了唯物辩证的自然观、唯物辩证的认识论和唯物辩证的社会历史观的高度统一，宣告了真正彻底而完备的唯物主义哲学的产生。(2)唯物史观的创立，使社会主义由空想变成了科学。(3)唯物史观的创立，为人们认识和研究社会历史提供了科学的世界观和方法论，使社会科学第一次有可能成为真正意义上的科学。(4)唯物史观是无产阶级及其政党制定路线、方针、政策的理论依据，是我们确立共产主义世界观、历史观、价值观、人生观，走历史必由之路，从事社会主义实践的理论指南。三、生产方式对社会发展的影响作用生产方式是人类借以向自然界谋取必需的生活资料的方式，包括生产力和生产关系两个方面，是特定的生产力和生产关系的统一。生产方式在社会展中起决定作用，主要表现在以下几个方面：(1)生产方式或生产活动，是人类从动物界分离出来的根本动力和人类区别于动物的根本标志。(2)生产方式或生产活动是人类和人类社会得以存在和发展的基础。(3)生产话动是形成人类一切社会关系的基础。(4)生产方式决定社会制度的性质和社会制度的更替。四、生产力的含义及特征生产力是在人的劳动中形成并为人直接掌握的物质力量，生产力只属于人，是人的本质力量的体现，也是人的实践能力的衡量尺度。生产力的主要征是客观性、社会性和历史性。五、生产关系的含义及构成要素生产关系是指同生产力发展一定阶段相联系的、人们在生产中形成的客观物质关系。生产关系作为一种客观的物质关系，其主要特征就是客观性。生产关系是一个具有复杂结构的系统，由三个方面构成：生产资料的所有制关系、人们在生产中的地位和交换关系、产品分配关系以及由它直接决定的消费关系。其中，生产资料的所有制关系是最基本的、具有决定意义的方面，是生产关系的基础。公有制为主体、多种所有制经济共同发展，是我国社会主义初级阶段的基本经济制度，也是我国社会现阶段生产关系的基本内容。',
    tags: ['历年真题'],
