    analysis: '领导阶级不同:旧民主主义革命由资产阶级及其政党领导;新民主主义革命的领导者是无产阶级,旧民主主义革命属于世界资产阶级革命的一部分;新民主主义革命发生在十月革命之后,属于无产阶级世界革命的一部分。在这些不同中,因为领导阶级的不同引申了其它的不同,因此根本区别应该是领导阶级的不同。考点 3：社会主义本质和初级阶段理论内容提要：了解社会主义本质理论的形成及其意义;准确掌握社会主义初级阶段理论的形成及其主要内容;深刻理解党在社会主义初级阶段的基本路线、基本纲领,特别是分“三步走”基本实现现代化的经济社会发展战略。一、社会主义本质理论的重大指导意义(1)社会主义本质理论继承了科学社会主义的基本原则，是探索建设中特色社会主义道路的最重大的理论成果之一，是对马克思主义的重大发展。(2)社会主义本质理论为我们既坚持公有制，又完善和发展公有制指明了方向。(3)社会主义本质理论突破了把计划经济等一些原本不属于社会主义固有的东西当作社会主义本质特征的传统观念。(4)社会主义本质理论反映了人民的利益和时代的要求，澄清了不合乎时代进步和社会发展规律的模糊观念，摆脱了长期以来拘泥于具体模式而忽视社会主义本质的错误倾向，深化了人们对社会主义本质的认识。二、社会主义的根本任务是发展生产力的原因(1)马克思主义最注重发展生产力。(2)发展生产力是社会主义的内在要求。(3)发展生产力是显示社会主义制度优越性和巩固社会主义制度的需要。(4)社会主义初级阶段的主要矛盾决定社会主义的根本任务是发展生产力。三、社会主义初级阶段长期性的原因(1)我国将长期处于社会主义初级阶段，是由中国社会主义建设的历史前提决定的。(2)我国将长期处于社会主义初级阶段，是由我国经济、社会发展现状决定的。(3)我国将长期处于社会主义初级阶段，是由我国社会主义现代化建设所处的国际环境决定的。四、社会主义的根本任务是发展生产力发展生产力是马克思主义的一个基本思想,是实现共产主义的物质基础。生产力是人类社会发展的最终决定力量和最根本的推动力。社会的进步也是生产力推动的,衡量社会进步的标准是生产力发展。发展生产力是社会主义本质的内在要求。只有不断发展生产力,创造出比资本主义更高的劳动生产率,创造出更丰富的物质和精神财富,才能逐步提高人民的物质和文化生活水平,最终实现共同富裕的目标。发展生产力,是巩固社会主义制度的需要。衡量一种社会制度、衡量一种所有制是否优越的标准在于是否促进生产力的发展。如果生产力发展了,国家的综合国力就能极大增强,可以有效地抵御资本主义势力的扩张,达到巩固社会主义制度的目的。发展生产力是解决社会主义初级阶段主要矛盾的根本手段。五、“全面建设小康社会”奋斗目标的新要求第一,增强发展协调性,努力实现经济又好又快发展。转变发展方式取得重大进展,在优化结构、提高效益、降低消耗、保护环境的基础上,实现人均国内生产总值到 2020年比 2000年翻两番。社会主义市场经济体制更加完善。自主创新能力显著提高,科技进步对经济增长的贡献率大幅上升,进入创新型国家行列。居民消费率稳步提高,形成消费、投资、出口协调拉动的增长格局。城乡、区域协调互动发展机制和主体功能区布局基本形成。社会主义新农村建设取得重大进展。城镇人口比重明显增加。第二,扩大社会主义民主,更好保障人民权益和社会公平正义。公民政治参与有序扩大.依法治国基本方略深人落实,全社会法制观念进一步增强,法治政府建设取得新成效。基层民主制度更加完善。政府提供基本公共服务能力显著增强。第三,加强文化建设,明显提高全民族文明素质,社会主义核心价值体系深人人心,良好思想道德风尚进一步弘扬。覆盖全社会的公共文化服务体系基本建立,文化产业占国民经济比重明显提高、国际竞争力显著增强,适应人民需要的文化产品更加丰富。第四,加快发展社会事业,全面改善人民生活。现代国民教育体系更加完善,终身教育体系基本形成,全民受教育程度和创新人才培养水平明显提高。社会就业更加充分。覆盖城乡居民的社会保障体系基本建立,人人享有基本生活保障。合理有序的收人分配格局基本形成，中等收入者占多数,绝对贫困现象基本消除。人人享有基本医疗卫生服务。社会管理体系更加健全。第五,建设生态文明,基本形成节约能源资源和保护生态环境的产业结构、增长方式、消费模式。循环经济形成较大规模,可再生能源比重显著上升。主要污染物排放得到有效控制,生态环境质量明显改善。生态文明观念在全社会牢固树立。',
    tags: ['历年真题'],
