    answer: ['D'],
    analysis: '社会主义的根本任务是发展生产力,党和国家的工作重点是经济建设,这是对我国社会主义建设经验教训和社会主要矛盾进行科学分析得出的最重要的结论,是解决当代中国一切问题的关键。坚持以经济建设为中心不动摇,就是从根本上坚持了党的基本路线。考点 4：社会主义改革和对外开放内容提要：了解我国改革开放的依据、历程和成就；深刻理解改革开放是决定当代中国命运的关键抉择、我国必须坚定不移地推进全面改革，不断提高对外开放水平。一、社会主义社会的基本矛盾毛泽东关于社会主义社会矛盾的理论:第一，社会主义社会仍然存在矛盾。第二，社会主义社会的矛盾是非对抗性的矛盾。第三，敌我矛盾和人民内部矛盾。二、邓小平关于社会主义社会矛盾的理论在新的历史时期，邓小平坚持和发展了毛泽东关于社会主义社会矛盾的学说，从而为社会主义改革的发展提供了深刻的哲学依据。第一，判断一种生产关系和生产力的发展是否相适应，主要看它是否适应当地生产力的发展，能否推动生产力的发展。第二，社会主义社会仍然存在一个解放生产力的问题。第三，把社会主义社会的基本矛盾、主要矛盾和根本任务统一起来。第四，解决社会主义社会主要矛盾的途径是改革，不是阶级斗争。三、改革是中国的第二次革命的原因(1)改革是为了扫除生产力发展的障碍，解放生产力。革命是解放生产力，改革也是解放生产力，从这个意义上说，改革也可以叫做革命。(2)改革是对原有体制进行的根本性变革。我国目前的改革不同于社会正常发展中始终会存在的解决社会基本矛盾的一般性变革，而是对存在着严重弊端的旧体制进行全面的重大变革，特别是对经济体制进行全面创新，把原有高度集中的计划经济体制转变为社会主义市场经济体制。(3)改革引起了经济生活、社会生活、思想观念等一系列重大变化。改革是在党的领导下对原有经济体制和其他体制进行根本性变革，改革是社会主义制度的自我完善和发展。四、正确处理改革、发展、稳定的关系发展是目的，改革是动力，稳定是前提。正确认识和处理改革、发展、稳定三者的辩证关系具有重要意义。能否正确认识和处理改革、发展、稳定三者的辩证关系，是社会主义改革事业成败的关键；正确认识和处理改革、发展、稳定三者的辩证关系，可以使我们在实践中更好地坚持前进的方向，减少失误，少走弯路；正确认识和处理改革、发展、稳定三者的辩证关系，有助于培养人们的辩证头脑，有助于树立全局观念，有助于确立战略眼光，增强人们在工作中分析事物、把握规律的能力。五、我国对外开放的成就(1)对外经济贸易实现历史性飞跃。(2)引进外资不断升级，推动全面对外开放格局的形成。(3)“走出去”战略稳步推进。(4)加入世贸组织，对外开放不断扩大。六、不断提高对外开放水平的具体做法(1)要统筹安排对内对外经济工作。(2)加快转变外贸发展方式，优化进出口商品结构。(3)继续实施“引进来”和“走出去”的战略，创新对外投资和合作方式。开放带来进步，封闭必然落后。进入新时代，中国开放的大门不会关闭，只会越开越大。我们要在以习近平同志为总书记的党中央领导下，高举邓小平理论、“三个代表”重要思想、科学发展观的伟大旗帜，在各项工作中全面准确贯彻落实习近平新时代中国特色社会主义思想。以“一带一路"建设为重点，坚持引进来和走出去并重，遵循共商共建共享原则，加强创新能力开放合作，形成陆海内外联动、东西双向互济的开放格局。',
