    answer: ['D'],
    analysis: '独立自主,自力更生,无论过去、现在和将来,都是我们革命和建设的立足点。我国是一个主权独立的社会主义国家,必须维护国家的政治、经济的独立自主权利,决不做外国的附庸,决不吞下外国损害我国利益的苦果。考点 5：建设中国特色社会主义经济内容提要：了解社会主义初级阶段的基本经济制度和分配制度；深刻理解实行以公有制为主体、多种所有制经济共同发展的经济制度，以及建立社会主义市场经济体制的历史必然性；深刻理解让一部分地区、一部分人先富起来最终实现共同富裕的重要思想；深刻理解我国促进国民经济又好又快发展的重要方针。一、以公有制为主体、多种所有制经济共同发展的必然性党的十五大报告指出：“公有制为主体，多种所有制经济共同发展，是我国社会主义初级阶段的一项基本经济制度。”这是由我国的基本国情决定的。(1)我国是社会主义国家，必须坚持公有制作为社会主义经济制度的基础。(2)我国处在社会主义初级阶段，需要在公有制为主体的条件下发展多种所有制经济。(3)一切符合“三个有利于”的所有制的形式都可以而且应该用来为社会主义服务。二、公有制主体地位的体现及坚持公有制主体地位的原因在我国社会主义初级阶段，公有制主体地位主要体现在以下几个方面：(1)公有资产在社会总资产中占优势。(2)国有经济控制国民经济命脉，对经济发展起主导作用。国有经济起主导作用，主要体现在控制力上。在社会主义初级阶段，必须坚持公有制为的主体地位。这是因为：首先，生产资料公有制是社会主义的一条根本原则；其次，坚持公有制的主体地位是社会生产力发展的客观要求；再次，坚持公有制的主体地位是保证其他所有制经济为社会主义服务的决定性条件；最后，坚持公有制的主体地位是贯彻按劳分配，实现共同富裕的根本保证。三、按劳分配的内容及其必然性按劳分配的内容是：凡是有劳动能力的人都应尽自己的能力为社会劳动，社会以劳动作为分配个人消费品的尺度，按照劳动者提供的劳动数量和质量分配个人消费品，等量劳动获取等量报酬，多劳多得，少劳少得，不劳动者不得食。社会主义社会在个人消费品分配领域必然实行按劳分配原则。第一，社会主义初级阶段生产资料公有制，是实行按劳分配的前提条件；第二，社会主义初级阶段生产力的发展水平，是实行按劳分配的物质基础；第三，社会主义初级阶段劳动本身所具有的特点，是实行按劳分配的直接原因。四、社会主义初级阶段实行以按劳分配为主体，多种分配方式并存的客观必然性以按劳分配为主体、多种分配方式同时并存，是我国社会主义初级阶段的个人收人分配制度。这是由我国社会主义初级阶段的客观经济条件决定的。(1)以公有制为主体、多种所有制经济长期共同发展的所有制结构，决定了以按劳分配为主体、多种分配方式同时并存的分配结构。(2)公有制实现形式的多样化也决定了分配形式的多样化。(3)它是社会主义市场经济体制的内在要求。五、社会主义市场经济体制的基本特征(1)在所有制结构上，以公有制为主体，多种所有制经济共同发展，一切符合“三个有利于”的所有制形式都可以而且应该用来为社会主义服务。(2)在分配制度上，坚持以按劳分配为主体、多种分配方式并存的制度。(3)在宏观调控上，由于存在着作为主体的公有制经济的人民民主专政的社会义国家政权，国家对市场的调控具有较雄厚的物质基础、牢固的政治基础和广泛的群众基础，对市场的宏观调控能力可以较资本主义国家强得多。',
