    options: ['爱国、敬业、诚信、友善', '富强、民主、文明、和谐', '自由、平等、公正、法治', '和平、发展、互利、共赢'],
    answer: ['B'],
    analysis: '富强、民主、文明、和谐,是国家层面的价值目标;自由、平等、公正、法治,是社会层面的价值取向;爱国、敬业、诚信、友善,是公民个人层面的价值准则。考点 9：国际战略和外交政策内容提要：了解国际形势发展变化的特点；准确掌握我国对国际形势的判断以及友国独立自主的和平外交政策的内容和目标；深刻理解我国走和平发展道路的历史必然性。一、邓小平对和平与发展是当今时代主题的判断的基本点(1)世界大战在一个相当长的时期内可以避免,我们有可能争取较长时期的和平环境。(2)和平与发展是当今世界两大带有全球性的战略问题,是东西方之间、发达国家与发展中国家之间矛盾全局的集中体现。(3)和平与发展是相辅相成的,世界和平是促进各国共同发展的前提条件,各国的共同发展则是保持世界和平的重要基础。(4)和平与发展成为时代主题,并不意味着这两个问题已经解决。二、中国坚定不移地奉行独立自主的和平外交政策的具体做法中国坚定不移地奉行独立自主的和平外交政策,是由我国的社会主义性质和在国际上的地位决定的。坚持独立自主的和平外交政策,就是把国家主权和安全放在第一位,坚定地维护我国的国家利益,反对任何国家损害我国的独立、主权、安全和尊严；就是从我国人民和世界人民的根本利益出发,对于一切国际事务,都要根据事情本身的是非曲直,决定自己的立场和政策,不屈从于任何外来压力;就是坚持各国的事务应由本国政府和人民决定,世界上的事情应由各国政府和人民平等协商,反对一切形式的霸权主义和强权政治;就是不以社会制度和意识形态的异同决定国家关系的亲疏,而是坚持在和平共处五项原则基础上同所有国家建立和发展友好关系;就是坚持不同任何大国或大国集团结盟,不搞军事集团,不参加军备竞赛,不进行军事扩张,永远不谋求霸权。三、独立自主的和平外交政策的基本原则(1)坚持独立自主地处理一切国际事务的原则。(2)坚持和平共处五项原则为指导国家间关系的基本准则。(3)坚持同发展中国家加强团结与合作的原则。(4)坚持爱国主义与履行国际义务相统一的原则。四、维护世界和平、构建和谐世界的具体做法(1)反对霸权主义和强权政治,维护世界和平与发展。(2)维护世界多样性,促进国际关系民主化和发展模式多样化。(3)树立新的安全观念,努力营造长期稳定的国际和平环境。(4)推动建设持久和平与共同繁荣的和谐世界。',
