    answerText: '习近平总书记指出：“中国式现代化，是中国共产党领导的社会主义现代化，既有各国现代化的共同特征，更有基于自己国情的中国特色。”党的二十大集中概括了中国式现代化五个方面的中国特色，深刻揭示了中国式现代化的科学内涵，这是理论概括，也是实践要求。 (1)中国式现代化是人口规模巨大的现代化； (2)中国式现代化是全体人民共同富裕的现代化； (3)中国式现代化是物质文明和精神文明相协调的现代化； (4)中国式现代化是人与自然和谐共生的现代化； (5)中国式现代化是走和平发展道路的现代化。',
